from pathlib import Path
import pandas as pd,numpy as np,json
A=Path(__file__).resolve().parents[1];R=A.parent;P=A/'panel_evidence';O=P/'outputs'
p=pd.read_parquet(R/'outputs/empirical/positions.parquet');p=p[p.date.between('2025-01-15','2026-03-30')];m=p.groupby(['market','date'])[['market_supply','market_borrow']].first().reset_index().sort_values(['market','date'])
for col in ['market_supply','market_borrow']:m['delta_'+col]=m.groupby('market')[col].diff()
m['previous_date']=m.groupby('market').date.shift();m=m[(pd.to_datetime(m.date)-pd.to_datetime(m.previous_date)).dt.days.eq(1)];d=pd.read_parquet(O/'market_operation_daily.parquet');m=m.merge(d,on=['market','date'],validate='one_to_one');m['supply_stock_minus_net_supply_micro']=m.delta_market_supply-m.supply_flow_micro;m['interest_from_supply_balance_micro']=m.supply_stock_minus_net_supply_micro+m.bad_debt_micro;m['borrow_reconciliation_error_micro']=m.delta_market_borrow-(m.borrow_flow_micro+m.interest_from_supply_balance_micro-m.liquidation_repaid_micro-m.bad_debt_micro);assert m.borrow_reconciliation_error_micro.eq(0).all();m.to_csv(O/'supply_stock_flow_reconciliation.csv',index=False,float_format='%.0f')
r={'market_days':len(m),'raw_supply_stock_identity_over_1USDC':int(m.supply_stock_minus_net_supply_micro.abs().gt(1000000).sum()),'max_raw_supply_difference_USDC':float(m.supply_stock_minus_net_supply_micro.abs().max()/1e6),'after_interest_and_bad_debt_error_micro':int(m.borrow_reconciliation_error_micro.abs().max()),'interest_definition':'interest implied by supply stock-flow balance, separately reported from observed operations'};(P/'supply_identity_checks.json').write_text(json.dumps(r,indent=2));print(r)
